#include <iostream>

struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x) : val(x), next(nullptr) {}
};

class LinkedSublistReversal {
public:
    // Core structural implementation for bounded section inversion
    ListNode* reverseBetween(ListNode* head, int p, int q) {
        if (!head || p == q) {
            return head;
        }

        ListNode* curr = head;
        ListNode* prev = nullptr;
        int index = 1;

        // Phase 1: Advance pointers until reaching the sub-list entry point
        while (curr != nullptr && index < p) {
            prev = curr;
            curr = curr->next;
            index++;
        }

        // Isolate your two upstream boundary connection points
        ListNode* lastNodeOfFirstPart = prev;
        ListNode* lastNodeOfSubList = curr;

        // Phase 2: Invert the links within the active window [p, q]
        ListNode* nextNode = nullptr;
        while (curr != nullptr && index <= q) {
            nextNode = curr->next;
            curr->next = prev; // Invert reference mapping direction
            prev = curr;       // Advance trailing tracker
            curr = nextNode;   // Advance leading tracker
            index++;
        }

        // Phase 3: Stitch the inverted sub-list back into the main chain
        if (lastNodeOfFirstPart != nullptr) {
            lastNodeOfFirstPart->next = prev; // Connect prefix chain to sub-list head
        } else {
            head = prev; // Sub-list started at index 1 -> update global entry point
        }

        lastNodeOfSubList->next = curr; // Connect sub-list tail to suffix chain

        return head;
    }
};

